### Instruction:
Write a JavaScript program to convert an array of objects into a comma-separated values (CSV) string with column headers.

### Input:
[
 {name: 'John', age: 28, city: 'New York'}, 
 {name: 'Mary', age: 34, city: 'London'}, 
 {name: 'Bob', age: 23, city: 'Los Angeles'}
]

### Response:
function arrayToCSV(data) {
  let csv = '';
  const headers = Object.keys(data[0]);
  csv += headers.join(',') + '\n';
  data.forEach((item) => {
    let row = '';
    Object.values(item).forEach((value) => {
      row += `"${value}",`;
    });
    row = row.slice(0, -1);
    csv += `${row}\n`;
  });
  return csv;
}

