						script: ["echo"],
						postProcess: function (out, tokens) {
							const colonParams = ["http", "https", "who", "time"];
							let token = ":";
							if (tokens[1].match(":[^:]*")) {
								token = tokens[1];
							} else if (tokens[2] && tokens[2].match(":[^:]+")) {
								token = tokens[2];
							}
