  return !!(
    window.document &&
    window.document.featurePolicy &&
    window.document.featurePolicy.allowsFeature('sync-xhr')
  );
}

export function gt(a: string = '', b: string = ''): boolean {
  return compareVersions(a, b) === 1;
}

export function gte(a: string = '', b: string = ''): boolean {
  return compareVersions(a, b) > -1;
}

export const isReactNativeEnvironment = (): boolean => {
  // We've been relying on this for such a long time
  // We should probably define the client for DevTools on the backend side and share it with the frontend
  return window.document == null;
};

// 0.123456789 => 0.123
// Expects high-resolution timestamp in milliseconds, like from performance.now()
// Mainly used for optimizing the size of serialized profiling payload
export function formatDurationToMicrosecondsGranularity(
  duration: number,
): number {
  return Math.round(duration * 1000) / 1000;
}

var ENV = ENV || (function() {

  var first = true;
  var counter = 0;
  var data;
  var _base;
  (_base = String.prototype).lpad || (_base.lpad = function(padding, toLength) {
    return padding.repeat((toLength - this.length) / padding.length).concat(this);
  });

  function formatElapsed(value) {
    var str = parseFloat(value).toFixed(2);
    if (value > 60) {
      minutes = Math.floor(value / 60);
      comps = (value % 60).toFixed(2).split('.');
      seconds = comps[0].lpad('0', 2);
      ms = comps[1];
      str = minutes + ":" + seconds + "." + ms;
    }
    return str;
  }

  function getElapsedClassName(elapsed) {
    var className = 'Query elapsed';
    if (elapsed >= 10.0) {
      className += ' warn_long';
    }
    else if (elapsed >= 1.0) {
      className += ' warn';
    }
    else {
      className += ' short';
    }
    return className;
  }

  function countClassName(queries) {
    var countClassName = "label";
    if (queries >= 20) {
      countClassName += " label-important";
    }
    else if (queries >= 10) {
      countClassName += " label-warning";
    }
    else {
      countClassName += " label-success";
    }
    return countClassName;
  }

  function updateQuery(object) {
    if (!object) {
      object = {};
    }
    var elapsed = Math.random() * 15;
    object.elapsed = elapsed;
    object.formatElapsed = formatElapsed(elapsed);
    object.elapsedClassName = getElapsedClassName(elapsed);
    object.query = "SELECT blah FROM something";
    object.waiting = Math.random() < 0.5;
    if (Math.random() < 0.2) {
      object.query = "<IDLE> in transaction";
    }
    if (Math.random() < 0.1) {
      object.query = "vacuum";
    }
    return object;
  }

  function cleanQuery(value) {
    if (value) {
      value.formatElapsed = "";
      value.elapsedClassName = "";
      value.query = "";
      value.elapsed = null;
      value.waiting = null;
    } else {
      return {
        query: "***",
        formatElapsed: "",
        elapsedClassName: ""
      };
    }
  }

  function generateRow(object, keepIdentity, counter) {
    var nbQueries = Math.floor((Math.random() * 10) + 1);
    if (!object) {
      object = {};
    }
    object.lastMutationId = counter;
    object.nbQueries = nbQueries;
    if (!object.lastSample) {
      object.lastSample = {};
    }
    if (!object.lastSample.topFiveQueries) {
      object.lastSample.topFiveQueries = [];
    }
    if (keepIdentity) {
      // for Angular optimization
      if (!object.lastSample.queries) {
        object.lastSample.queries = [];
        for (var l = 0; l < 12; l++) {
          object.lastSample.queries[l] = cleanQuery();
        }
      }
      for (var j in object.lastSample.queries) {
        var value = object.lastSample.queries[j];
        if (j <= nbQueries) {
          updateQuery(value);
        } else {
          cleanQuery(value);
        }
      }
    } else {
      object.lastSample.queries = [];
      for (var j = 0; j < 12; j++) {
        if (j < nbQueries) {
          var value = updateQuery(cleanQuery());
          object.lastSample.queries.push(value);
        } else {
          object.lastSample.queries.push(cleanQuery());
        }
      }
    }
    for (var i = 0; i < 5; i++) {
      var source = object.lastSample.queries[i];
      object.lastSample.topFiveQueries[i] = source;
    }
    object.lastSample.nbQueries = nbQueries;
    object.lastSample.countClassName = countClassName(nbQueries);
    return object;
  }

  function getData(keepIdentity) {
    var oldData = data;
    if (!keepIdentity) { // reset for each tick when !keepIdentity
      data = [];
      for (var i = 1; i <= ENV.rows; i++) {
        data.push({ dbname: 'cluster' + i, query: "", formatElapsed: "", elapsedClassName: "" });
        data.push({ dbname: 'cluster' + i + ' slave', query: "", formatElapsed: "", elapsedClassName: "" });
      }
    }
    if (!data) { // first init when keepIdentity
      data = [];
      for (var i = 1; i <= ENV.rows; i++) {
        data.push({ dbname: 'cluster' + i });
        data.push({ dbname: 'cluster' + i + ' slave' });
      }
      oldData = data;
    }
    for (var i in data) {
      var row = data[i];
      if (!keepIdentity && oldData && oldData[i]) {
        row.lastSample = oldData[i].lastSample;
      }
      if (!row.lastSample || Math.random() < ENV.mutations()) {
        counter = counter + 1;
        if (!keepIdentity) {
          row.lastSample = null;
        }
        generateRow(row, keepIdentity, counter);
      } else {
        data[i] = oldData[i];
      }
    }
    first = false;
    return {
      toArray: function() {
        return data;
      }
    };
  }

  var mutationsValue = 0.5;

  function mutations(value) {
    if (value) {
      mutationsValue = value;
      return mutationsValue;
    } else {
      return mutationsValue;
    }
  }

  var body = document.querySelector('body');
  var theFirstChild = body.firstChild;

  var sliderContainer = document.createElement( 'div' );
  sliderContainer.style.cssText = "display: flex";
  var slider = document.createElement('input');
  var text = document.createElement('label');
  text.innerHTML = 'mutations : ' + (mutationsValue * 100).toFixed(0) + '%';
  text.id = "ratioval";
  slider.setAttribute("type", "range");
  slider.style.cssText = 'margin-bottom: 10px; margin-top: 5px';
  slider.addEventListener('change', function(e) {
    ENV.mutations(e.target.value / 100);
    document.querySelector('#ratioval').innerHTML = 'mutations : ' + (ENV.mutations() * 100).toFixed(0) + '%';
  });
  sliderContainer.appendChild( text );
  sliderContainer.appendChild( slider );
  body.insertBefore( sliderContainer, theFirstChild );

  return  {
    generateData: getData,
    rows: 50,
    timeout: 0,
    mutations: mutations
  };
})();

const args = require('minimist')(process.argv.slice(2))
const fs = require('fs')
const path = require('path')
const chalk = require('chalk')
const semver = require('semver')
const currentVersion = require('../package.json').version
const { prompt } = require('enquirer')
const execa = require('execa')

const preId =
  args.preid ||
  (semver.prerelease(currentVersion) && semver.prerelease(currentVersion)[0])
const isDryRun = args.dry
const skipTests = args.skipTests
const skipBuild = args.skipBuild
const packages = fs
  .readdirSync(path.resolve(__dirname, '../packages'))
  .filter(p => !p.endsWith('.ts') && !p.startsWith('.'))
  .concat('vue')

const versionIncrements = [
  'patch',
  'minor',
  'major',
  ...(preId ? ['prepatch', 'preminor', 'premajor', 'prerelease'] : [])
]

const inc = i => semver.inc(currentVersion, i, preId)
const run = (bin, args, opts = {}) =>
  execa(bin, args, { stdio: 'inherit', ...opts })
const dryRun = (bin, args, opts = {}) =>
  console.log(chalk.blue(`[dryrun] ${bin} ${args.join(' ')}`), opts)
const runIfNotDry = isDryRun ? dryRun : run
const step = msg => console.log(chalk.cyan(msg))

async function main() {
  let targetVersion = args._[0]

  if (!targetVersion) {
    // no explicit version, offer suggestions
    const { release } = await prompt({
      type: 'select',
      name: 'release',
      message: 'Select release type',
      choices: versionIncrements.map(i => `${i} (${inc(i)})`).concat(['custom'])
    })

    if (release === 'custom') {
      targetVersion = (
        await prompt({
          type: 'input',
          name: 'version',
          message: 'Input custom version',
          initial: currentVersion
        })
      ).version
    } else {
      targetVersion = release.match(/\((.*)\)/)[1]
    }
  }

  if (!semver.valid(targetVersion)) {
    throw new Error(`invalid target version: ${targetVersion}`)
  }

  const { yes } = await prompt({
    type: 'confirm',
    name: 'yes',
    message: `Releasing v${targetVersion}. Confirm?`
  })

  if (!yes) {
    return
  }

  // run tests before release
  step('\nRunning tests...')
  if (!skipTests && !isDryRun) {
    await run('pnpm', ['test'])
  } else {
    console.log(`(skipped)`)
  }

  // update all package versions and inter-dependencies
  step('\nUpdating package versions...')
  packages.forEach(p => updatePackage(getPkgRoot(p), targetVersion))

  // build all packages with types
  step('\nBuilding all packages...')
  if (!skipBuild && !isDryRun) {
    await run('pnpm', ['run', 'build'])
    if (skipTests) {
      await run('pnpm', ['run', 'build:types'])
    }
  } else {
    console.log(`(skipped)`)
  }

  // generate changelog
  step('\nGenerating changelog...')
  await run(`pnpm`, ['run', 'changelog'])

  // update pnpm-lock.yaml
  step('\nUpdating lockfile...')
  await run(`pnpm`, ['install', '--prefer-offline'])

  const { stdout } = await run('git', ['diff'], { stdio: 'pipe' })
  if (stdout) {
    step('\nCommitting changes...')
    await runIfNotDry('git', ['add', '-A'])
    await runIfNotDry('git', ['commit', '-m', `release: v${targetVersion}`])
  } else {
    console.log('No changes to commit.')
  }

  // publish packages
  step('\nPublishing packages...')
  for (const pkg of packages) {
    await publishPackage(pkg, targetVersion, runIfNotDry)
  }

  // push to GitHub
  step('\nPushing to GitHub...')
  await runIfNotDry('git', ['tag', `v${targetVersion}`])
  await runIfNotDry('git', ['push', 'origin', `refs/tags/v${targetVersion}`])
  await runIfNotDry('git', ['push'])

  if (isDryRun) {
    console.log(`\nDry run finished - run git diff to see package changes.`)
  }
  console.log()
}

function updatePackage(pkgRoot, version) {
  const pkgPath = path.resolve(pkgRoot, 'package.json')
  const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'))
  pkg.version = version
  fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n')
}

const getPkgRoot = pkg =>
  pkg === 'vue'
    ? path.resolve(__dirname, '../')
    : path.resolve(__dirname, '../packages/' + pkg)

async function publishPackage(pkgName, version, runIfNotDry) {
  const pkgRoot = getPkgRoot(pkgName)
  const pkgPath = path.resolve(pkgRoot, 'package.json')
  const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'))
  const publishedName = pkg.name
  if (pkg.private) {
    return
  }

  let releaseTag = null
  if (args.tag) {
    releaseTag = args.tag
  } else if (version.includes('alpha')) {
    releaseTag = 'alpha'
  } else if (version.includes('beta')) {
    releaseTag = 'beta'
  } else if (version.includes('rc')) {
    releaseTag = 'rc'
  }

  // avoid overwriting tags for v3
  if (pkgName === 'vue' || pkgName === 'compiler-sfc') {
    if (releaseTag) {
      releaseTag = `v2-${releaseTag}`
    } else {
      releaseTag = 'v2-latest'
    }
  }

  step(`Publishing ${publishedName}...`)
  try {
    await runIfNotDry(
      'pnpm',
      [
        'publish',
        ...(releaseTag ? ['--tag', releaseTag] : []),
        '--access',
        'public'
      ],
      {
        cwd: pkgRoot,
        stdio: 'pipe'
      }
    )
    console.log(
      chalk.green(`Successfully published ${publishedName}@${version}`)
    )
  } catch (e) {
    if (e.stderr.match(/previously published/)) {
      console.log(chalk.red(`Skipping already published: ${publishedName}`))
    } else {
      throw e
    }
  }
}

main()

import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { rollup } from 'rollup';
import virtual from '@rollup/plugin-virtual';
import { nodeResolve } from '@rollup/plugin-node-resolve';
import { compile } from 'svelte/compiler';

/**
 * @param {string} entry
 */
async function bundle_code(entry) {
	const bundle = await rollup({
		input: '__entry__',
		plugins: [
			virtual({
				__entry__: entry
			}),
			{
				name: 'resolve-svelte',
				resolveId(importee) {
					if (importee.startsWith('svelte')) {
						const entry = pkg.exports[importee.replace('svelte', '.')];
						return path.resolve(entry.browser ?? entry.default);
					}
				}
			},
			nodeResolve({
				exportConditions: ['production', 'import', 'browser', 'default']
			})
		],
		onwarn: (warning, handle) => {
			if (warning.code !== 'EMPTY_BUNDLE' && warning.code !== 'CIRCULAR_DEPENDENCY') {
				handle(warning);
			}
		}
	});

	const { output } = await bundle.generate({});

	if (output.length > 1) {
		throw new Error('errr what');
	}

	return output[0].code.trim();
}

const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));

let failed = false;

// eslint-disable-next-line no-console
console.group('checking treeshakeability');

for (const key in pkg.exports) {
	// special cases
	if (key === './compiler') continue;
	if (key === './internal') continue;
	if (key === './internal/disclose-version') continue;
	if (key === './internal/flags/legacy') continue;
	if (key === './internal/flags/tracing') continue;

	for (const type of ['browser', 'default']) {
		if (!pkg.exports[key][type]) continue;

		const subpackage = path.join(pkg.name, key);
		const resolved = path.resolve(pkg.exports[key][type]);
		const code = await bundle_code(`import ${JSON.stringify(resolved)}`);

		if (code === '') {
			// eslint-disable-next-line no-console
			console.error(`✅ ${subpackage} (${type})`);
		} else {
			// eslint-disable-next-line no-console
			console.error(code);
			// eslint-disable-next-line no-console
			console.error(`❌ ${subpackage} (${type})`);
			failed = true;
		}
	}
}

const client_main = path.resolve(pkg.exports['.'].browser);
const bundle = await bundle_code(
	// Use all features which contain hydration code to ensure it's treeshakeable
	compile(
		`
<svelte:options runes />
<script>
	import { mount } from ${JSON.stringify(client_main)}; mount();
	let foo;
</script>

<svelte:head><title>hi</title></svelte:head>
<input bind:value={foo} />

<a href={foo} class={foo}>a</a>
<a {...foo}>a</a>
<svelte:component this={foo} />
<svelte:element this={foo} />
<C {foo} />

{#if foo}
{/if}
{#each foo as bar}
{/each}
{#await foo}
{/await}
{#key foo}
{/key}
{#snippet x()}
{/snippet}

{@render x()}
{@html foo}
	`,
		{ filename: 'App.svelte' }
	).js.code
);

/**
 * @param {string} case_name
 * @param {string[]} strings
 */
function check_bundle(case_name, ...strings) {
	for (const string of strings) {
		const index = bundle.indexOf(string);
		if (index >= 0) {
			// eslint-disable-next-line no-console
			console.error(`❌ ${case_name} not treeshakeable`);
			failed = true;

			let lines = bundle.slice(index - 500, index + 500).split('\n');
			const target_line = lines.findIndex((line) => line.includes(string));
			// mark the failed line
			lines = lines
				.map((line, i) => (i === target_line ? `> ${line}` : `| ${line}`))
				.slice(target_line - 5, target_line + 6);
			// eslint-disable-next-line no-console
			console.error('The first failed line:\n' + lines.join('\n'));
			return;
		}
	}
	// eslint-disable-next-line no-console
	console.error(`✅ ${case_name} treeshakeable`);
}

check_bundle('Hydration code', 'hydrate_node', 'hydrate_next');
check_bundle('Legacy code', 'component_context.l');
check_bundle('$inspect.trace', `'CreatedAt'`);

if (failed) {
	// eslint-disable-next-line no-console
	console.error('Full bundle at', path.resolve('scripts/_bundle.js'));
	fs.writeFileSync('scripts/_bundle.js', bundle);
}

// eslint-disable-next-line no-console
console.groupEnd();

if (failed) {
	process.exit(1);
}

/** @import { Node } from 'esrap/languages/ts' */
/** @import * as ESTree from 'estree' */
/** @import { AST } from 'svelte/compiler' */

// @ts-check
import process from 'node:process';
import fs from 'node:fs';
import * as acorn from 'acorn';
import { walk } from 'zimmerframe';
import * as esrap from 'esrap';
import ts from 'esrap/languages/ts';

const DIR = '../../documentation/docs/98-reference/.generated';

const watch = process.argv.includes('-w');

function run() {
	/** @type {Record<string, Record<string, { messages: string[], details: string | null }>>} */
	const messages = {};
	const seen = new Set();

	fs.rmSync(DIR, { force: true, recursive: true });
	fs.mkdirSync(DIR);

	for (const category of fs.readdirSync('messages')) {
		if (category.startsWith('.')) continue;

		messages[category] = {};

		for (const file of fs.readdirSync(`messages/${category}`)) {
			if (!file.endsWith('.md')) continue;

			const markdown = fs
				.readFileSync(`messages/${category}/${file}`, 'utf-8')
				.replace(/\r\n/g, '\n');

			const sorted = [];

			for (const match of markdown.matchAll(/## ([\w]+)\n\n([^]+?)(?=$|\n\n## )/g)) {
				const [_, code, text] = match;

				if (seen.has(code)) {
					throw new Error(`Duplicate message code ${category}/${code}`);
				}

				sorted.push({ code, _ });

				const sections = text.trim().split('\n\n');
				const details = [];

				while (!sections[sections.length - 1].startsWith('> ')) {
					details.unshift(/** @type {string} */ (sections.pop()));
				}

				if (sections.length === 0) {
					throw new Error('No message text');
				}

				seen.add(code);
				messages[category][code] = {
					messages: sections.map((section) => section.replace(/^> /gm, '').replace(/^>\n/gm, '\n')),
					details: details.join('\n\n')
				};
			}

			sorted.sort((a, b) => (a.code < b.code ? -1 : 1));

			fs.writeFileSync(
				`messages/${category}/${file}`,
				sorted.map((x) => x._.trim()).join('\n\n') + '\n'
			);
		}

		fs.writeFileSync(
			`${DIR}/${category}.md`,
			'<!-- This file is generated by scripts/process-messages/index.js. Do not edit! -->\n\n' +
				Object.entries(messages[category])
					.map(([code, { messages, details }]) => {
						const chunks = [
							`### ${code}`,
							...messages.map((message) => '```\n' + message + '\n```')
						];

						if (details) {
							chunks.push(details);
						}

						return chunks.join('\n\n');
					})
					.sort()
					.join('\n\n') +
				'\n'
		);
	}

	/**
	 * @param {string} name
	 * @param {string} dest
	 */
	function transform(name, dest) {
		const source = fs
			.readFileSync(new URL(`./templates/${name}.js`, import.meta.url), 'utf-8')
			.replace(/\r\n/g, '\n');

		/** @type {AST.JSComment[]} */
		const comments = [];

		let ast = /** @type {ESTree.Node} */ (
			/** @type {unknown} */ (
				acorn.parse(source, {
					ecmaVersion: 'latest',
					sourceType: 'module',
					locations: true,
					onComment: comments
				})
			)
		);

		comments.forEach((comment) => {
			if (comment.type === 'Block') {
				comment.value = comment.value.replace(/^\t+/gm, '');
			}
		});

		ast = walk(ast, null, {
			Identifier(node, context) {
				if (node.name === 'CODES') {
					/** @type {ESTree.ArrayExpression} */
					const array = {
						type: 'ArrayExpression',
						elements: Object.keys(messages[name]).map((code) => ({
							type: 'Literal',
							value: code
						}))
					};

					return array;
				}
			}
		});

		const body = /** @type {ESTree.Program} */ (ast).body;

		const category = messages[name];

		// find the `export function CODE` node
		const index = body.findIndex((node) => {
			if (
				node.type === 'ExportNamedDeclaration' &&
				node.declaration &&
				node.declaration.type === 'FunctionDeclaration'
			) {
				return node.declaration.id.name === 'CODE';
			}
		});

		if (index === -1) throw new Error(`missing export function CODE in ${name}.js`);

		const template_node = body[index];
		body.splice(index, 1);

		const jsdoc = /** @type {AST.JSComment} */ (
			comments.findLast((comment) => comment.start < /** @type {number} */ (template_node.start))
		);

		const printed = esrap.print(
			/** @type {Node} */ (ast),
			ts({
				comments: comments.filter((comment) => comment !== jsdoc)
			})
		);

		for (const code in category) {
			const { messages } = category[code];
			/** @type {string[]} */
			const vars = [];

			const group = messages.map((text, i) => {
				for (const match of text.matchAll(/%(\w+)%/g)) {
					const name = match[1];
					if (!vars.includes(name)) {
						vars.push(match[1]);
					}
				}

				return {
					text,
					vars: vars.slice()
				};
			});

			/** @type {ESTree.Expression} */
			let message = { type: 'Literal', value: '' };
			let prev_vars;

			for (let i = 0; i < group.length; i += 1) {
				const { text, vars } = group[i];

				if (vars.length === 0) {
					message = {
						type: 'Literal',
						value: text
					};
					prev_vars = vars;
					continue;
				}

				const parts = text.split(/(%\w+%)/);

				/** @type {ESTree.Expression[]} */
				const expressions = [];

				/** @type {ESTree.TemplateElement[]} */
				const quasis = [];

				for (let i = 0; i < parts.length; i += 1) {
					const part = parts[i];
					if (i % 2 === 0) {
						const str = part.replace(/(`|\${)/g, '\\$1');
						quasis.push({
							type: 'TemplateElement',
							value: { raw: str, cooked: str },
							tail: i === parts.length - 1
						});
					} else {
						expressions.push({
							type: 'Identifier',
							name: part.slice(1, -1)
						});
					}
				}

				/** @type {ESTree.Expression} */
				const expression = {
					type: 'TemplateLiteral',
					expressions,
					quasis
				};

				if (prev_vars) {
					if (vars.length === prev_vars.length) {
						throw new Error('Message overloads must have new parameters');
					}

					message = {
						type: 'ConditionalExpression',
						test: {
							type: 'Identifier',
							name: vars[prev_vars.length]
						},
						consequent: expression,
						alternate: message
					};
				} else {
					message = expression;
				}

				prev_vars = vars;
			}

			const clone = /** @type {ESTree.Statement} */ (
				walk(/** @type {ESTree.Node} */ (template_node), null, {
					FunctionDeclaration(node, context) {
						if (node.id.name !== 'CODE') return;

						const params = [];

						for (const param of node.params) {
							if (param.type === 'Identifier' && param.name === 'PARAMETER') {
								params.push(...vars.map((name) => ({ type: 'Identifier', name })));
							} else {
								params.push(param);
							}
						}

						return /** @type {ESTree.FunctionDeclaration} */ ({
							.../** @type {ESTree.FunctionDeclaration} */ (context.next()),
							params,
							id: {
								...node.id,
								name: code
							}
						});
					},
					TemplateLiteral(node, context) {
						/** @type {ESTree.TemplateElement} */
						let quasi = {
							type: 'TemplateElement',
							value: {
								...node.quasis[0].value
							},
							tail: node.quasis[0].tail
						};

						/** @type {ESTree.TemplateLiteral} */
						let out = {
							type: 'TemplateLiteral',
							quasis: [quasi],
							expressions: []
						};

						for (let i = 0; i < node.expressions.length; i += 1) {
							const q = structuredClone(node.quasis[i + 1]);
							const e = node.expressions[i];

							if (e.type === 'Literal' && e.value === 'CODE') {
								quasi.value.raw += code + q.value.raw;
								continue;
							}

							if (e.type === 'Identifier' && e.name === 'MESSAGE') {
								if (message.type === 'Literal') {
									const str = /** @type {string} */ (message.value).replace(/(`|\${)/g, '\\$1');
									quasi.value.raw += str + q.value.raw;
									continue;
								}

								if (message.type === 'TemplateLiteral') {
									const m = structuredClone(message);
									quasi.value.raw += m.quasis[0].value.raw;
									out.quasis.push(...m.quasis.slice(1));
									out.expressions.push(...m.expressions);
									quasi = m.quasis[m.quasis.length - 1];
									quasi.value.raw += q.value.raw;
									continue;
								}
							}

							out.quasis.push((quasi = q));
							out.expressions.push(/** @type {ESTree.Expression} */ (context.visit(e)));
						}

						return out;
					},
					Literal(node) {
						if (node.value === 'CODE') {
							return {
								type: 'Literal',
								value: code
							};
						}
					},
					Identifier(node) {
						if (node.name !== 'MESSAGE') return;
						return message;
					}
				})
			);

			const jsdoc_clone = {
				...jsdoc,
				value: /** @type {string} */ (jsdoc.value)
					.split('\n')
					.map((line) => {
						if (line === ' * MESSAGE') {
							return messages[messages.length - 1]
								.split('\n')
								.map((line) => ` * ${line}`)
								.join('\n');
						}

						if (line.includes('PARAMETER')) {
							return vars
								.map((name, i) => {
									const optional = i >= group[0].vars.length;

									return optional
										? ` * @param {string | undefined | null} [${name}]`
										: ` * @param {string} ${name}`;
								})
								.join('\n');
						}

						return line;
					})
					.filter((x) => x !== '')
					.join('\n')
			};

			const block = esrap.print(
				// @ts-expect-error some bullshit
				/** @type {ESTree.Program} */ ({ ...ast, body: [clone] }),
				ts({ comments: [jsdoc_clone] })
			).code;

			printed.code += `\n\n${block}`;

			body.push(clone);
		}

		fs.writeFileSync(
			dest,
			`/* This file is generated by scripts/process-messages/index.js. Do not edit! */\n\n` +
				printed.code,
			'utf-8'
		);
	}

	transform('compile-errors', 'src/compiler/errors.js');
	transform('compile-warnings', 'src/compiler/warnings.js');

	transform('client-warnings', 'src/internal/client/warnings.js');
	transform('client-errors', 'src/internal/client/errors.js');
	transform('server-warnings', 'src/internal/server/warnings.js');
	transform('server-errors', 'src/internal/server/errors.js');
	transform('shared-errors', 'src/internal/shared/errors.js');
	transform('shared-warnings', 'src/internal/shared/warnings.js');
}

if (watch) {
	let running = false;
	let timeout;

	fs.watch('messages', { recursive: true }, (type, file) => {
		if (running) {
			timeout ??= setTimeout(() => {
				running = false;
				timeout = null;
			});
		} else {
			running = true;

			// eslint-disable-next-line no-console
			console.log('Regenerating messages...');
			run();
		}
	});
}

run();

