static ALGORITHM: &aws_lc_rs::signature::EcdsaSigningAlgorithm =
  &aws_lc_rs::signature::ECDSA_P256_SHA256_ASN1_SIGNING;

struct KeyMaterial {
  pub _case: &'static str,
  pub certificate: String,
