    cache
      .set_cjs_analysis("file.js", CacheDBHash::new(2), &cjs_analysis)
      .unwrap();
    assert!(
      cache
        .get_cjs_analysis("file.js", CacheDBHash::new(3))
        .unwrap()
        .is_none()
