    // now changing the cli version should clear it
    let conn = cache.conn.recreate_with_version("2.0.0");
    let cache = NodeAnalysisCacheInner::new(conn);
    assert!(
      cache
        .get_cjs_analysis("file.js", CacheDBHash::new(2))
        .unwrap()
        .is_none()
    );
  }
