fn component_version(component: &str) -> Option<(String, Status)> {
  Command::new(component)
    .arg("-V")
    .output()
    .map(|o| String::from_utf8_lossy(o.stdout.as_slice()).to_string())
    .map(|v| {
      format!(
        "{component}: {}",
        v.split('\n')
          .next()
          .unwrap()
          .strip_prefix(&format!("{component} "))
          .unwrap_or_default()
      )
    })
    .map(|desc| (desc, Status::Success))
    .ok()
}

