{'code': 'def split_adhoc_filters_into_base_filters(fd):
    """
    Mutates form data to restructure the adhoc filters in the form of the four base
    filters, `where`, `having`, `filters`, and `having_filters` which represent
    free form where sql, free form having sql, structured where clauses and structured
    having clauses.
    """
    adhoc_filters = fd.get('adhoc_filters')
    if isinstance(adhoc_filters, list):
        simple_where_filters = []
        simple_having_filters = []
        sql_where_filters = []
        sql_having_filters = []
        for adhoc_filter in adhoc_filters:
            expression_type = adhoc_filter.get('expressionType')
            clause = adhoc_filter.get('clause')
            if expression_type == 'SIMPLE':
                if clause == 'WHERE':
                    simple_where_filters.append({
                        'col': adhoc_filter.get('subject'),
                        'op': adhoc_filter.get('operator'),
                        'val': adhoc_filter.get('comparator'),
                    })
                elif clause == 'HAVING':
                    simple_having_filters.append({
                        'col': adhoc_filter.get('subject'),
                        'op': adhoc_filter.get('operator'),
                        'val': adhoc_filter.get('comparator'),
                    })
            elif expression_type == 'SQL':
                if clause == 'WHERE':
                    sql_where_filters.append(adhoc_filter.get('sqlExpression'))
                elif clause == 'HAVING':
                    sql_having_filters.append(adhoc_filter.get('sqlExpression'))
        fd['where'] = ' AND '.join(['({})'.format(sql) for sql in sql_where_filters])
        fd['having'] = ' AND '.join(['({})'.format(sql) for sql in sql_having_filters])
        fd['having_filters'] = simple_having_filters
        fd['filters'] = simple_where_filters', 'language': 'python', 'source': 'codesearchnet'}

{'code': 'def kth_to_last_eval(head, k):
    """
    This is a suboptimal, hacky method using eval(), which is not
     safe for user input. We guard against danger by ensuring k in an int
    """
    if not isinstance(k, int) or not head.val:
        return False

    nexts = '.'.join(['next' for n in range(1, k+1)])
    seeker = str('.'.join(['head', nexts]))

    while head:
        if eval(seeker) is None:
            return head
        else:
            head = head.next

    return False', 'language': 'python', 'source': 'codesearchnet'}

