{  
    // To remove leading spaces  
    while (str.StartsWith(" "))  
    {  
        str = str.Substring(1);  
    }  

    // To remove trailing spaces  
    while (str.EndsWith(" "))  
    {  
        str = str.Substring(0, str.Length - 1);  
    }  

    return str;  
}

