### Instruction:
Write a search engine using an index in JavaScript.

### Response:
// create an index
let index = {};

// add a document to the index
let addDocument = (document, content) => {
  let words = content.split(' ');
  words.forEach((word) => {
    if (index.hasOwnProperty(word)) {
      //if the word is already in the index, add the document to its list
      index[word].push(document);
    } else {
      //add the word to the index
      index[word] = [document];
    }
  });
};

// perform a search
let search = (query) => {
  //array to hold the found documents
  let found = [];

  query.split(' ').forEach((word) => {
    //check if word is in index
    if (index.hasOwnProperty(word)) {
      index[word].forEach((doc) => {
        //make sure document isn't already in the list
        if (found.indexOf(doc) == -1) {
          found.push(doc);
        }
      });
    }
  });

  //return the found documents
  return found;
};

