### Input:
String input = "HelloWorld";

### Response:
public static String[] stringToArray(String input) {
    String[] stringArray = new String[input.length()/4];
    int count = 0;
    for (int i = 0; i < input.length(); i += 4) {
        stringArray[count] = input.substring(i, i+4);
        count++;
    }
    return stringArray;
}

