### Response:
function checkVowels(str) {
  const sortedVowels = 'aeiou'.split('').sort().join('');
  const sortedStr = str
    .toLowerCase()
    .split('')
    .filter(letter => ['a','e','i','o','u'].includes(letter))
    .sort()
    .join('');
  return sortedVowels === sortedStr;
}

