def count_vowels(text):
    """Given a string text, count the number of vowels in the string using a loop."""

### Solution:

    vowel_count = 0
    for char in text:
        if char.lower() in 'aeiou':
            vowel_count += 1
    return vowel_count

### Problem:
def reverse_words(text):
    """Given a string text, reverse the order of words in the string using a loop."""

### Solution:

    words = text.split()
    reversed_text = ''
    for i in range(len(words) - 1, -1, -1):
        reversed_text += words[i] + ' '
    return reversed_text.strip()

