def count_repeated_characters(string):

    """
    This function takes a string as input and counts the number of repeated characters.
    """

### Solution:


    repeated_characters = {}

    for char in string:
        if char not in repeated_characters:
            repeated_characters[char] = 1
        else:
            repeated_characters[char] += 1

    for char, count in repeated_characters.items():
        if count > 1:
            print(f"{char}: {count}")

