def common_elements(set1, set2):
    """Given two sets, return a new set containing only the common elements between them."""

### Solution:


    # Initialize an empty set to store the common elements
    common_set = set()

    if isinstance(set1, set) and isinstance(set2, set):
        # Check if both inputs are sets

        # Iterate over each element in set1
        for element in set1:
            if element in set2:
                # Check if the element is present in set2

                if isinstance(element, str):
                    # Check if the common element is a string
                    if element.lower() == element[::-1].lower():
                        # Check if the string is a palindrome
                        common_set.add(element)
                else:
                    # Check if the common element is a number
                    if element % 2 == 0:
                        # Check if the number is even
                        common_set.add(element)

    # Return the final set of common elements
    return common_set
